# Let's try with -C for demangling and -p for pretty print, and also try nm for the SGen worker addresses
SYMFILE="/tmp/sv-fae0e1cf204e4f78ba94f620e3b9449f/mono.sym"

# Try getting function names from the symbol table for the ones that showed $d.147
echo "=== Using nm to find functions at SGen worker addresses ==="
# Find function containing 0x2f4b20 and 0x2f4c84
nm -n "$SYMFILE" 2>/dev/null | grep -i " [tT] " | awk -v addr1="2f4b20" -v addr2="2f4c84" '
BEGIN { prev_addr=""; prev_name="" }
{
  cur_addr = $1
  if (prev_addr != "" && strtonum("0x" prev_addr) <= strtonum("0x" addr1) && strtonum("0x" cur_addr) > strtonum("0x" addr1)) {
    printf "0x%s is in function: %s (at 0x%s)\n", addr1, prev_name, prev_addr
  }
  if (prev_addr != "" && strtonum("0x" prev_addr) <= strtonum("0x" addr2) && strtonum("0x" cur_addr) > strtonum("0x" addr2)) {
    printf "0x%s is in function: %s (at 0x%s)\n", addr2, prev_name, prev_addr
  }
  prev_addr = cur_addr
  prev_name = $3
}'

