# The symtab size field might be in hex - let me check the format
SYMFILE="/tmp/sv-fae0e1cf204e4f78ba94f620e3b9449f/mono.sym"

# Just dump symbols near 0x2f4000 range
readelf -s -W "$SYMFILE" 2>/dev/null | grep -i "FUNC" | awk '{
  addr = strtonum("0x" $2)
  if (addr >= 0x2f4000 && addr <= 0x2f5000) print
}' | head -20

echo "---"
# Also try nearby with dynamic syms
readelf --dyn-syms -W "$SYMFILE" 2>/dev/null | grep -i "FUNC" | awk '{
  addr = strtonum("0x" $2)
  if (addr >= 0x2f0000 && addr <= 0x300000) print
}' | head -20

