arguments.command:
# The $d.147 symbols are ARM mapping symbols (data markers). Let me search for FUNC entries that contain our addresses
SYMFILE="/tmp/sv-fae0e1cf204e4f78ba94f620e3b9449f/mono.sym"

# Get all FUNC symbols sorted by address and find which contains 0x2f4b20 and 0x2f4c84
readelf -s -W "$SYMFILE" 2>/dev/null | awk '
$4 == "FUNC" && $2 != "0000000000000000" {
  print strtonum("0x" $2), $3, $8
}' | sort -n | awk '
{
  addr = $1; size = $2; name = $3
  if (addr <= 0x2f4b20 && (addr + size) > 0x2f4b20) printf "0x2f4b20 in %s (0x%x + %d)\n", name, addr, size
  if (addr <= 0x2f4c84 && (addr + size) > 0x2f4c84) printf "0x2f4c84 in %s (0x%x + %d)\n", name, addr, size
}' 

echo "---"
# Also find what's close to those addresses
readelf -s -W "$SYMFILE" 2>/dev/null | awk '
$4 == "FUNC" {
  addr = strtonum("0x" $2)
  if (addr >= 0x2f4000 && addr <= 0x2f5000) printf "  0x%x size=%s %s\n", addr, $3, $8
}' | sort

