  addr = strtonum("0x" $2)
  size = strtonum($3)
  name = $8
  if (addr > 0 && size > 0) printf "%d %d %s\n", addr, size, name
}' | sort -n | awk '
{
  addr = $1; size = $2; name = $3
  if (addr <= 3099424 && (addr + size) > 3099424) printf "0x2f4b20 in %s (base=0x%x, size=%d, offset=0x%x)\n", name, addr, size, 3099424-addr
  if (addr <= 3099780 && (addr + size) > 3099780) printf "0x2f4c84 in %s (base=0x%x, size=%d, offset=0x%x)\n", name, addr, size, 3099780-addr
}'

echo "=== Closest FUNC before 0x2f4b20 ==="
readelf -s -W "$SYMFILE" --dyn-syms 2>/dev/null | awk '
$4 == "FUNC" {
  addr = strtonum("0x" $2)
  size = strtonum($3)
